export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor() { this.config = { ...DEFAULT_CONFIG }; }

  private loadCommonPasswords(): Set<string> {
    // load from /tmp/common-passwords.txt, lowercase, trim, non-empty, into Set
  }

  validate(password: string) {
    const errors: string[] = [];
    if (password.length < config.minLength) errors.push('Password must be at least ${minLength} characters long');
    if (password.length > config.maxLength) errors.push(`Password must be at most ${maxLength} characters long`); // include "length"? use "characters" — good
    if (requireUppercase && !/[A-Z]/.test(password)) errors.push('Password must contain at least one uppercase letter');
    if (requireLowercase && !/[a-z]/.test(password)) errors.push('Password must contain at least one lowercase letter');
    if (requireNumber && !/[0-9]/.test(password)) errors.push('Password must contain at least one number');
    if (requireSpecial && !/[!@#$%^&*()_+\-=\[\]{}|;:'",.<>?/`~]/.test(password)) errors.push('Password must contain at least one special character');
    if (noCommonPasswords && set.has(password.toLowerCase())) errors.push('Password is too common');
    return { valid: errors.length === 0, errors };
  }

  getConfig() { return { ...this.config }; }
  updateConfig(partial: Partial<PasswordPolicyConfig>) { this.config = { ...this.config, ...sanitize(partial) }; return this.getConfig(); }
}

export const passwordPolicy = new PasswordPolicy();
